'use strict';
const $=(id)=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={user:null,csrf:'',page:'start',authTab:'signup',profile:{mode:'고입',region:'광주',grade:'중1',schoolTrack:'일반고',middleGrades:{},highGrades:[],targetSchool:'',researchMonths:0,weeklyHours:8},answers:{},plan:{major:'',daily:[],weekly:[],monthly:[],yearly:[],weeklyHours:8,advanceRatio:30,measurement:''},questions:[],surveyPage:0,surveyFilter:'all',surveyCategory:'관심·진로',report:null,caseId:null,adminCaseId:null,official:[],schools:[],schoolQuery:'',cases:[],adminCases:[],adminStudents:[],review:null,authBusy:false,nodeId:1,nodeCount:1,nodeCapacity:25};
const regions=['서울','부산','대구','인천','광주','대전','울산','세종','경기','강원','충북','충남','전북','전남','경북','경남','제주'];
const modes=[['고입','중학생의 고교 선택·성적·학교 적합성'],['중학생 장기 대입','현재 학습부터 2030 대입 등 장기 설계'],['대입','내신·모의고사·계열과 대학전형'],['재수/N수','목표 전형·수능 성적·재도전 학습'],['검정고시','인정학력·지원자격·이후 진학'],['편입','대학교 GPA·이수학점·편입요건'],['대학생 진로','전공·취업·대학원 방향'],['대학원','전공·학업역량·연구 방향']];
const subjects=['국어','수학','영어','과학','사회','역사','도덕','기술·가정','정보','체육','음악','미술'];const terms=['1-1','1-2','2-1','2-2','3-1','3-2'];
const navStudent=[['start','시작 안내'],['profile','1. 내 기본정보'],['grades','2. 성적 입력'],['studentRecord','3. 생기부·세특 기록'],['goals','4. 목표 학교·진로'],['aiStudio','5. AI 심층 분석'],['inbox','6. 전문상담원 상담'],['plan','7. 주간 학습 캘린더'],['mypage','내 계정']];
const navAdvanced=[['survey','168문항 진로탐색'],['result','규칙 기반 자동진단'],['aiPlanner','12주 자동 계획'],['schoolLab','전국학교 검색'],['universityLab','대학 기본정보'],['trajectory','목표·성적 그래프'],['plusAnalytics','학습 성과 리포트'],['sources','공식 근거 자료']];
state.showAdvanced=false;
const navAdmin=[['queue','상담 접수함'],['editor','최종 컨설팅 작성'],['students','학생 회원 관리'],['catalog','공식 학교 자료 등록'],['apiManager','API 키·사용량 관리'],['sources','근거 자료실'],['mypage','관리자 마이페이지']];
async function api(url,data){const opt={credentials:'same-origin',headers:{'Accept':'application/json'}};if(data!==undefined){opt.method='POST';opt.headers['Content-Type']='application/json';opt.headers['X-CSRF']=state.csrf;opt.body=JSON.stringify(data)}const r=await fetch(url,opt);let j;try{j=await r.json()}catch{throw Error('서버에서 응답을 읽지 못했습니다.')};if(!r.ok)throw Error(j.error||'요청이 실패했습니다.');return j}
function alertx(txt){const n=document.createElement('div');n.className='toast';n.textContent=txt;document.body.appendChild(n);setTimeout(()=>n.remove(),4200)}
function error(e){alertx(e?.message||String(e))}
function mark(){return `<span class="mark">✦</span>`};
function brand(){return `<div class="brand">${mark()}<div>PATHFINDER <span style="color:#267fa0">EDU</span><small>EDUCATION CONSULTING</small></div></div>`}
function options(list,value){return list.map(x=>{let v,t;if(Array.isArray(x)){[v,t]=x}else{v=t=x}return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}
function getMode(){return state.profile.mode||'고입'}
function saveProfileField(el){if(!el?.dataset?.field)return;const f=el.dataset.field;state.profile[f]=el.type==='number'?(el.value===''?'':Number(el.value)):el.value}
function courseP(){return ['고입','중학생 장기 대입'].includes(getMode())}
function uniP(){return ['편입','대학원','대학생 진로'].includes(getMode())}
function renderLogin(){if(location.pathname==='/admin')state.authTab='admin';const signup=state.authTab==='signup',adm=state.authTab==='admin';$('root').innerHTML=`<div class="login-screen"><aside class="login-art"><img src="assets/flight-path.webp" alt="활주로 위의 석양"><div>${brand()}<div style="margin-top:65px"><p class="eyebrow" style="color:#b4d6e5">THE ROAD AHEAD</p><h1>가능성을 찾고,<br>계획으로 바꾸다.</h1><p>한 번의 결과보다 다음 학기의 변화를 생각합니다.<br>학생과 상담자가 함께 완성하는 진학·학습 플랫폼.</p></div></div><div class="muted" style="color:#bdccd7">학생별 개인정보와 학업기록을 구분하는 시범 상담 도구</div></aside><section class="login-panel"><div class="login-box"><div class="eyebrow">WELCOME TO PATHFINDER</div><h2 style="margin:8px 0">${signup?'학생 회원가입':adm?'관리자 로그인':'학생 로그인'}</h2>${state.nodeCount>1?`<div class="notice"><b>PATHFINDER ${state.nodeId}조 / 전체 ${state.nodeCount}조</b> · 이 서버 학생 정원 ${state.nodeCapacity}명<br>가입과 로그인은 배정된 조의 서버 주소에서만 가능합니다.${state.nodeId===1?' 관리자는 /admin으로 로그인합니다.':''}</div>`:''}<p class="muted">${signup?'정보와 동의를 확인한 후 상담을 시작합니다.':adm?'상담 접수함·자료실·결과지 발송을 관리합니다.':'이어서 분석하고 학습계획을 조정할 수 있습니다.'}</p><div class="switch">${location.pathname==='/admin'?'':`<button data-auth="signup" class="${signup?'active':''}">학생 회원가입</button><button data-auth="student" class="${state.authTab==='student'?'active':''}">학생 로그인</button>`}${location.pathname==='/admin'?`<button data-auth="admin" class="${adm?'active':''}">관리자 로그인</button>`:''}</div><form id="authForm">${signup?`<label>이름 또는 별칭<input required name="name" maxlength="40" placeholder="예: 김학생"></label><label>출생연도<input required name="birthYear" type="number" min="1940" max="2020" placeholder="예: 2011"></label>`:''}<label>아이디<input required name="username" autocomplete="username" placeholder="영문/숫자 4자 이상"></label><label>비밀번호<input required type="password" name="password" minlength="${signup?10:1}" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'10자 이상':'비밀번호'}"></label>${signup?`<label>초대 코드 (온라인 운영 시 필수)<input name="signupCode" autocomplete="off" placeholder="운영자가 전달한 가입 코드"></label><div class="soft privacy"><b>개인정보 처리 안내 — 비공개 시험 운영</b><p style="margin:8px 0">수집: 계정 아이디·비밀번호 해시·이름(별칭)·출생연도·사용자가 입력한 성적·설문·학습계획. 목적: 분석, 상담, 결과지 전달. 서버 데이터는 직접 계정 삭제 시 삭제됩니다. 시험 운영 종료 시 관리자도 데이터베이스를 삭제해야 합니다. 상용 서비스의 세부 보유기간은 별도 확정·고지가 필요합니다.</p><p>동의하지 않으면 가입할 수 없습니다. 만 14세 미만 법정대리인 확인이 구현되지 않아 본 데모 가입이 제한됩니다. 선택한 AI 외부 검토만 별도 동의 후 학습계획을 전송할 수 있습니다.</p></div><label class="check"><input type="checkbox" name="consent" required><span>위 서비스·개인정보 처리 안내를 확인하고 필수 항목에 동의합니다.</span></label>`:''}<button class="btn" style="width:100%">${signup?'가입하고 시작하기':'로그인'}</button></form>${location.pathname==='/admin'?'<a href="/" class="fieldhint">학생 사이트로 돌아가기</a>':''}<p class="privacy" style="margin-top:17px">${signup?'아직 등록된 회원이 없다면 가입한 뒤 학생 로그인을 선택하세요.':adm?'관리자가 전달한 초기 비밀번호는 로그인 뒤 반드시 변경하세요.':'성적이 적어도 자체 진로탐색부터 시작할 수 있습니다.'}</p><div class="notice" style="margin-top:18px">이 프로그램은 제한된 인원용 시범 서비스입니다. 실제 결제·14세 미만 법정대리인 인증·상용 보안 심사는 제공되지 않습니다.</div></div></section></div>`;
 document.querySelectorAll('[data-auth]').forEach(x=>x.onclick=()=>{state.authTab=x.dataset.auth;renderLogin()});$('authForm').onsubmit=async(e)=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(state.authBusy)return;state.authBusy=true;try{if(signup){await api('/api/signup',{username:d.username,password:d.password,name:d.name,birthYear:+d.birthYear,signupCode:d.signupCode||'',consent:!!d.consent});state.authTab='student';renderLogin();alertx('회원가입 완료. 학생 계정으로 로그인하세요.')}else{await api('/api/login',{username:d.username,password:d.password,role:adm?'admin':'student'});await boot()}}catch(e){error(e)}finally{state.authBusy=false}}}
function shell(){const admin=state.user?.role==='admin';const nav=admin?navAdmin:(state.showAdvanced?[...navStudent,...navAdvanced]:navStudent);return `<div class="portal"><header class="topbar">${brand()}<div class="row"><span class="pill grey">${admin?'상담 관리자':'학생 · '+esc(state.user.display_name)}</span><button class="btn alt small" id="logout">로그아웃</button></div></header><div class="layout"><aside class="sidebar"><h3>${admin?'ADMINISTRATOR':'MY JOURNEY'}</h3>${nav.map(([id,t])=>`<button class="nav-btn ${id===state.page?'active':''}" data-page="${id}">${esc(t)}</button>`).join('')}<div class="sidebar-promo"><b>근거 중심 컨설팅</b><div>지원 가능 여부는 해당 모집연도 최종 모집요강으로 검토합니다. 예측을 사실처럼 표시하지 않습니다.</div></div>${admin?'':`<button class="nav-btn advanced-toggle" id="showAdvanced">${state.showAdvanced?'기본 메뉴만 보기':'추가 기능 펼치기'}</button>`}</aside><main class="content" id="pageContent"></main></div></div>`}
function render(){if(!state.user)return renderLogin();$('root').innerHTML=shell();document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{state.page=e.dataset.page;render()});if($('showAdvanced'))$('showAdvanced').onclick=()=>{state.showAdvanced=!state.showAdvanced;render()};$('logout').onclick=async()=>{try{await api('/api/logout',{})}catch{}state.user=null;renderLogin()};drawPage()}
function pageHeader(n,title,desc){return `<div class="head"><div><div class="eyebrow">${esc(n)}</div><h2 style="margin:5px 0 2px">${esc(title)}</h2><p>${esc(desc)}</p></div></div>`}
function drawPage(){const page=state.page;const f=({start,profile,grades,studentRecord,survey,goals,result,plan,trajectory,inbox,sources,mypage,queue,editor,students,catalog,aiStudio,schoolLab,universityLab,aiPlanner,plusAnalytics,apiManager})[page];if(!f)return;try{f()}catch(e){$('pageContent').innerHTML='<div class="card">오류가 발생했습니다: '+esc(e.message)+'</div>'}}
function start(){let html=`<div class="hero-panel banner"><img src="assets/orbit-editorial.webp" alt="지구와 우주 사진"><div><div class="eyebrow" style="color:#acdce5">PERSONAL EDUCATION PATHWAY</div><h1>당신만의 진학 경로를<br>계획으로 완성합니다.</h1><p>목적 선택 · 성적 · 168문항 탐색 · 학교 추천 · 학습계획 · 전문가 상담</p></div></div>${pageHeader('GET STARTED','진학 목적에 맞춰 설계합니다','진학 모드를 선택하면 입력·분석·추천이 각각 달라집니다.')}<div class="grid2">${modes.map(([m,t])=>`<div class="card"><div class="eyebrow">${esc(m)}</div><h3 style="margin:8px 0">${esc(t)}</h3><button class="btn alt small" data-setmode="${esc(m)}">이 경로로 시작 →</button></div>`).join('')}</div><div class="notice">중1처럼 성적 기록이 부족한 학생은 자체 진로탐색 설문으로 시작할 수 있습니다. IQ·공인 성향검사 결과는 산출하지 않습니다.</div>`;$('pageContent').innerHTML=html;document.querySelectorAll('[data-setmode]').forEach(b=>b.onclick=()=>{state.profile.mode=b.dataset.setmode;state.page='profile';render()})}
async function profile(){const p=state.profile;$('pageContent').innerHTML=`${pageHeader('STEP 01 · STUDENT PROFILE','학적·목표 기본정보','고입·대입·재수·편입·대학원에 맞게 분석 항목이 달라집니다.')}<section class="card airy"><div class="formgrid"><label>준비 목적<select data-field="mode">${options(modes,p.mode)}</select></label><label>현재 학년/상태<select data-field="grade">${options(['중1','중2','중3','고1','고2','고3','졸업생','검정고시','대학생','대학졸업'],p.grade)}</select></label><label>지역<select data-field="region">${options(regions,p.region)}</select></label><label>최종 졸업학력<select data-field="graduation">${options(['초등학교','중학교','고등학교','대학교','미졸업'],p.graduation)}</select></label><label>현재 재학 학교명<input data-field="currentSchool" value="${esc(p.currentSchool)}" placeholder="학교명"></label><label>목표 입학학년도<input type="number" data-field="goalYear" value="${esc(p.goalYear||'')}" placeholder="예: 2030" min="2027" max="2050"></label><label>관심 고교 유형<select data-field="schoolTrack">${options(['일반고','자율형 공립고','자율형 사립고','특성화고','마이스터고','과학고','영재학교','외국어고','국제고','예술고','체육고','미정'],p.schoolTrack)}</select></label><label>지속 탐구활동 기간(개월, 선택)<input type="number" min="0" max="100" data-field="researchMonths" value="${esc(p.researchMonths||0)}"></label><label>기숙사 선호<select data-field="dorm">${options(['무관','선호','비선호'],p.dorm)}</select></label><label>통학 가능 범위<select data-field="commute">${options(['30분 이내','60분 이내','90분 이내','기숙사도 가능','미정'],p.commute)}</select></label><label class="stretch">진로 관심·좋아했던 경험<textarea data-field="interestsNote" placeholder="활동을 직접 경험한 사실 위주로 기입">${esc(p.interestsNote)}</textarea></label></div><div class="footer-actions"><button class="btn" id="profileSave">저장하고 성적 입력 →</button></div></section>`;bindProfile();$('profileSave').onclick=async()=>{try{await api('/api/profile/save',{profile:state.profile});state.page='grades';render();alertx('학적 정보를 저장했습니다.')}catch(e){error(e)}}}
function bindProfile(){document.querySelectorAll('[data-field]').forEach(x=>x.addEventListener('input',()=>saveProfileField(x)))}
function grades(){const p=state.profile;const mid=courseP(),uni=uniP();const name=mid?'중학교 6학기':uni?'대학교 학점': '고교 내신·학점';let part='';if(mid){let vals=p.middleGrades||{};part=`<div class="notice">성적이 없거나 자유학기라면 비워두세요. 입력된 성적만 분석합니다. 성취도(A~E)는 학교 기준이 달라 원점수로 임의 환산하지 않습니다.</div><div class="table-wrap"><table class="table"><thead><tr><th>과목</th>${terms.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${subjects.map(s=>`<tr><td><b>${esc(s)}</b></td>${terms.map((t,i)=>`<td><input aria-label="${esc(s)} ${t}" type="number" min="0" max="100" data-score="${esc(s)}" data-term="${i}" value="${esc((vals[s]||[])[i]??'')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
 else if(uni){part=`<div class="formgrid"><label>대학교 현재 전공<input data-field="major" value="${esc(p.major)}"></label><label>총 취득학점<input type="number" data-field="credits" value="${esc(p.credits||'')}"></label><label>대학 GPA<input type="number" step="0.01" data-field="gpa" value="${esc(p.gpa||'')}"></label><label>GPA 만점<select data-field="gpaMax">${options(['4.5','4.3','4.0'],p.gpaMax)}</select></label></div>`}
 else{part=`<div class="notice">고등학교 과목마다 학점과 1~5등급을 따로 입력합니다. 대학별 환산식이 없어 단순 학점가중 참고 평균만 산출할 수 있습니다.</div><div class="table-wrap"><table class="table"><thead><tr><th>학기</th><th>과목</th><th>등급</th><th>학점</th><th>성취도</th><th>삭제</th></tr></thead><tbody>${(p.highGrades||[]).map((r,i)=>`<tr>${['semester','subject','grade','credits','achievement'].map(field=>`<td><input class="long" data-high="${i}" data-highfield="${field}" value="${esc(r[field])}" placeholder="${field==='semester'?'고1-1':''}"></td>`).join('')}<td><button class="btn alt small" data-delhigh="${i}">삭제</button></td></tr>`).join('')}</tbody></table></div><button class="btn alt small" id="addHigh" style="margin-top:15px">과목 추가</button><div class="formgrid"><label>국어 모의고사 등급<input data-field="examKorean" type="number" min="1" max="9" value="${esc(p.examKorean||'')}"></label><label>수학 모의고사 등급<input data-field="examMath" type="number" min="1" max="9" value="${esc(p.examMath||'')}"></label><label>영어 모의고사 등급<input data-field="examEnglish" type="number" min="1" max="9" value="${esc(p.examEnglish||'')}"></label><label>탐구 모의고사 등급<input data-field="examExplore" type="number" min="1" max="9" value="${esc(p.examExplore||'')}"></label></div>`}
 $('pageContent').innerHTML=`${pageHeader('STEP 02 · ACADEMIC RECORDS',name+' 성적 입력','실제 수치가 없는 학기는 비워도 되고, 새로운 시험 뒤 다시 업데이트할 수 있습니다.')}<div class="card airy">${part}<div class="formgrid"><label class="stretch">학업 기록 보완 설명<textarea data-field="gradesNote" placeholder="원점수나 등급을 해석할 때 유의해야 할 사항">${esc(p.gradesNote)}</textarea></label></div><div class="footer-actions"><button class="btn alt" data-page-next="profile">이전 단계</button><button class="btn" id="saveGrades">성적 저장·설문으로 →</button></div></div>`;
 bindProfile();document.querySelectorAll('[data-score]').forEach(x=>x.oninput=()=>{let a=p.middleGrades[x.dataset.score]||Array(6).fill('');a[+x.dataset.term]=x.value;p.middleGrades[x.dataset.score]=a});document.querySelectorAll('[data-high]').forEach(x=>x.oninput=()=>{p.highGrades[+x.dataset.high][x.dataset.highfield]=x.value});document.querySelectorAll('[data-delhigh]').forEach(x=>x.onclick=()=>{p.highGrades.splice(+x.dataset.delhigh,1);grades()});if($('addHigh'))$('addHigh').onclick=()=>{(p.highGrades||(p.highGrades=[])).push({semester:'고1-1',subject:'',grade:'',credits:'',achievement:''});grades()};bindNext();$('saveGrades').onclick=async()=>{try{await api('/api/profile/save',{profile:p});state.page='survey';render();alertx('성적 기록을 저장했습니다.')}catch(e){error(e)}}}
function bindNext(){document.querySelectorAll('[data-page-next]').forEach(x=>x.onclick=()=>{state.page=x.dataset.pageNext;render()})}
function filteredQ(){return state.surveyCategory==='전체'?state.questions:state.questions.filter(x=>x.category===state.surveyCategory)}
function survey(){let qs=filteredQ();const pageCount=Math.max(1,Math.ceil(qs.length/12));state.surveyPage=Math.min(state.surveyPage,pageCount-1);let page=qs.slice(state.surveyPage*12,(state.surveyPage+1)*12);let answered=Object.keys(state.answers).filter(k=>state.answers[k]!==undefined&&state.answers[k]!==null).length;
 $('pageContent').innerHTML=`${pageHeader('STEP 03 · EXPLORE YOURSELF','168문항 자체 진로·학습 탐색','성적 입력이 적은 중1도 시작할 수 있습니다. 공인 IQ·지능검사 결과는 제공하지 않습니다.')}<div class="card airy"><div class="row between"><div><span class="pill">${answered} / 168문항</span> <span class="muted">누락 문항은 빈 상태로 남겨둘 수 있습니다.</span></div><button class="btn alt small" id="saveSurvey">현재 답변 저장</button></div><div class="progress" style="margin:14px 0 20px"><div style="width:${Math.min(100,answered/168*100)}%"></div></div><div class="survey-controls">${['관심·진로','학습 습관','학교·가치관','추론 연습','전체'].map(x=>`<button class="tab ${state.surveyCategory===x?'active':''}" data-surveycat="${esc(x)}">${esc(x)}</button>`).join('')}</div><p class="fieldhint">관심·습관 문항: 1 전혀 아니다 ~ 5 매우 그렇다. 추론 연습은 총 12개 원본 퍼즐이며 <b>IQ 점수로 환산하지 않습니다.</b></p>${page.map((q,i)=>`<div class="q"><div class="q-num">${state.surveyPage*12+i+1}</div><div><div class="q-text">${esc(q.text)}</div><div class="opts">${(q.type==='reasoning'?q.options:['전혀 아니다','아니다','보통','그렇다','매우 그렇다']).map((label,j)=>{let v=q.type==='reasoning'?j:j+1;return `<label class="option"><input type="radio" name="q-${esc(q.id)}" data-answer="${esc(q.id)}" value="${v}" ${String(state.answers[q.id])===String(v)?'checked':''}>${esc(label)}</label>`}).join('')}</div></div></div>`).join('')}<div class="footer-actions"><button class="btn alt" id="surveyPrev" ${state.surveyPage===0?'disabled':''}>← 이전 문항</button><button class="btn alt" id="surveyNext" ${state.surveyPage+1>=pageCount?'disabled':''}>다음 12문항 →</button><button class="btn" id="surveyDone">답변 저장·목표 설정 →</button></div><div class="notice warn">이 문항은 PATHFINDER에서 자체 작성한 흥미·학습선호 탐색입니다. 표준화·타당도 검증이 없으므로 공인 심리검사·진단이나 지능지수 판정이 아닙니다. 공식 검사는 <a href="https://www.career.go.kr/" target="_blank" rel="noopener">커리어넷</a>에서 별도 진행하세요.</div></div>`;
 document.querySelectorAll('[data-answer]').forEach(x=>x.onchange=()=>state.answers[x.dataset.answer]=+x.value);document.querySelectorAll('[data-surveycat]').forEach(x=>x.onclick=()=>{state.surveyCategory=x.dataset.surveycat;state.surveyPage=0;survey()});$('surveyPrev').onclick=()=>{state.surveyPage--;survey()};$('surveyNext').onclick=()=>{state.surveyPage++;survey()};$('saveSurvey').onclick=async()=>{try{await api('/api/answers/save',{answers:state.answers});alertx('설문 응답을 저장했습니다.')}catch(e){error(e)}};$('surveyDone').onclick=async()=>{try{await api('/api/answers/save',{answers:state.answers});state.page='goals';render()}catch(e){error(e)}}}
async function goals(){const p=state.profile;$('pageContent').innerHTML=`${pageHeader('STEP 04 · FUTURE OPTIONS','목표 학교·학과와 원하는 환경','학교명만 고르면 합격이 가능해지는 것은 아닙니다. 실제 모집요강·지원자격을 따로 확인합니다.')}<div class="card airy"><div class="formgrid"><label>목표 학교 / 대학<input data-field="targetSchool" value="${esc(p.targetSchool)}" placeholder="지원 희망 학교명"></label><label>목표 학과/전공<input data-field="targetMajor" value="${esc(p.targetMajor)}" placeholder="아직 미정이어도 됩니다"></label><label>선호 경로<select data-field="careerPreference">${options(['미정','대학 진학','취업·실무','취업 후 진학','진로 재탐색'],p.careerPreference)}</select></label><label>주간 자율학습 가능 시간<input data-field="weeklyHours" type="number" min="0" max="70" value="${esc(p.weeklyHours??8)}"></label><label class="stretch">가장 관심 있는 활동<textarea data-field="activityNote" placeholder="지속 기간·구체적인 역할·성과가 있으면 좋습니다. 학생부 원문 제출은 요구하지 않습니다.">${esc(p.activityNote)}</textarea></label></div><div class="notice">전국 학교 12,004개의 기본 위치 데이터가 프로그램에 포함되어 있습니다. 단, 학교별 모집요강·전형·합격선은 별도 자료이므로 반드시 공식 원문 확인이 필요합니다.</div><div class="footer-actions"><button class="btn alt" data-page-next="survey">이전 단계</button><button class="btn" id="goalSubmit">저장하고 종합분석 →</button></div></div><div class="card" style="margin-top:19px"><h3>등록된 학교 검색</h3><div class="row"><input id="schoolSearch" placeholder="학교명 일부" style="flex:1"><button class="btn alt" id="schoolFind">검색</button></div><div id="schoolResults" class="result-list"><div class="muted">내장 전국학교 DB를 검색합니다. 검색된 학교가 실제 모집대상인지는 학교별로 다시 확인하세요.</div></div></div>`;bindProfile();bindNext();$('goalSubmit').onclick=async()=>{try{await api('/api/profile/save',{profile:p});await fetchAssessment();state.page='result';render()}catch(e){error(e)}};$('schoolFind').onclick=async()=>{try{let j=await api('/api/schools?name='+encodeURIComponent($('schoolSearch').value)+'&region='+encodeURIComponent(p.region||''));$('schoolResults').innerHTML=j.schools.length?j.schools.map(x=>`<div class="result"><b>${esc(x.name)}</b><small>${esc(x.region)} · ${esc(x.address)} · ${esc(x.level)}</small><p>${esc(x.verified)}</p></div>`).join(''):'<div class="empty">검색 결과 없음. 관리자 화면에서 공식 학교 CSV를 등록할 수 있습니다.</div>'}catch(e){error(e)}}}
async function fetchAssessment(){const r=await api('/api/assessment',{});state.report=r.assessment;return state.report}
function result(){const r=state.report;if(!r){$('pageContent').innerHTML=`${pageHeader('STEP 05 · CONSULTATION','종합 분석 결과','성적·설문·학교 목표를 저장한 다음 결과를 확인하세요.')}<div class="card"><button class="btn" id="calc">결과 생성</button></div>`;$('calc').onclick=async()=>{try{await fetchAssessment();render()}catch(e){error(e)}};return}
 const main=r.survey||{};const nums=r.grades||{};
 $('pageContent').innerHTML=`${pageHeader('STEP 05 · CONSULTATION','1차 진학 분석·상담 초안','학생에게 제공되는 자동 분석입니다. 최종 지원가능 판정과 전문 상담은 관리자가 별도로 검토합니다.')}<div class="hero-panel banner" style="min-height:155px"><img src="assets/orbit-editorial.webp" alt="교육과 미래"><div><span class="eyebrow">YOUR PATH, BASED ON EVIDENCE</span><h1 style="font-size:26px;margin:5px 0">${esc(r.area)}</h1><p>준비 목적: ${esc(r.mode)} | 목표: ${esc(r.goal||'아직 정하지 않음')}</p></div></div><div class="grid3"><div class="stat"><span>응답한 자체 진단 문항</span><strong>${esc(main.answered)} / 168</strong></div><div class="stat"><span>중학교 입력 성적 건수</span><strong>${esc(nums.records)}건</strong></div><div class="stat"><span>추론 연습</span><strong>${main.reasoning?.answered||0}문항</strong><small>IQ 아님</small></div></div><div class="cols" style="margin-top:20px"><div class="card"><h3>고교 유형·진학 경로 비교</h3><div class="result-list">${r.recommendations.map(x=>`<div class="result"><b>${esc(x.name)}</b><p>${esc(x.reason)}</p></div>`).join('')}</div></div><div class="card"><h3>관심 분야와 전공·학과 후보</h3><div class="result-list">${r.fieldOptions.map(x=>`<div class="result"><b>${esc(x)}</b></div>`).join('')}</div><div class="divider"></div><h3>권장 과목</h3><div class="row">${r.courses.map(x=>`<span class="pill grey">${esc(x)}</span>`).join('')}</div></div></div><div class="card" style="margin-top:20px"><h3>현재 학업 근거</h3>${nums.subjects?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>과목</th><th>최근점수</th><th>입력횟수</th><th>변화량</th></tr></thead><tbody>${nums.subjects.map(x=>`<tr><td>${esc(x.subject)}</td><td>${x.latest}</td><td>${x.count}</td><td>${x.change===null?'분석 불가':(x.change>0?'+':'')+x.change}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">성적 자료가 부족해 성향·관심 중심으로 분석합니다.</div>'}<div class="divider"></div><h3>12주 첫 실행 과제</h3>${r.roadmap.map(x=>`<div class="source"><b>${esc(x.week)}주차</b>　${esc(x.task)}</div>`).join('')}</div><div class="notice warn">${r.warnings.map(x=>`<div>• ${esc(x)}</div>`).join('')}<div>추론 연습 결과는 IQ가 아닙니다. 자신이 목표한 학교별 전형요강과 입결의 조건을 원문으로 확인하세요.</div></div><div class="footer-actions"><button class="btn alt" id="printResult">화면 인쇄</button><button class="btn" id="toPlan">목표 학과 선택·학습계획 작성 →</button><button class="btn alt" id="toTrajectory">학업·진로 그래프</button></div>`;
 $('printResult').onclick=()=>window.print();$('toTrajectory').onclick=()=>{state.page='trajectory';render()};$('toPlan').onclick=()=>{if(!state.plan.major&&r.fieldOptions[0])state.plan.major=r.fieldOptions[0];state.page='plan';render()}}
function rowPlans(key,label){const v=state.plan[key]||[];return `<div class="plan-level"><div class="row between"><h3>${esc(label)} 목표</h3><button class="btn alt small" data-addplan="${key}">+ 목표 추가</button></div><div class="group">${v.length?v.map((x,i)=>`<div class="plan-target"><input aria-label="${esc(label)} 목표 ${i+1}" data-planrow="${key}" data-index="${i}" value="${esc(x)}" placeholder="성과가 드러나는 목표를 작성하세요"><button class="btn alt small" data-delplan="${key}" data-index="${i}">삭제</button></div>`).join(''):'<small>아직 입력된 목표가 없습니다.</small>'}</div></div>`}
function plan(){const p=state.plan;$('pageContent').innerHTML=`${pageHeader('STEP 06 · STUDY ROADMAP','목표 학과부터 연간·월간·주간·일간 계획까지','직접 수정한 다음 규칙 기반 검토를 실행하고, 필요하면 별도 동의 후 외부 생성형 AI 검토를 요청할 수 있습니다.')}<div class="card airy"><div class="formgrid"><label>희망 계열 내 목표 학과<input data-plan="major" value="${esc(p.major)}" placeholder="예: 항공우주공학과"></label><label>주당 자율학습 가능 시간<input data-plan="weeklyHours" type="number" min="0" max="80" value="${esc(p.weeklyHours)}"></label><label>선행학습 비중 (%)<select data-plan="advanceRatio">${options([[0,'현행 100%'],[30,'현행 70% · 선행 30%'],[60,'현행 40% · 선행 60%']],p.advanceRatio)}</select></label><label>검증 지표<input data-plan="measurement" value="${esc(p.measurement)}" placeholder="예: 오답 재풀이 정답률 80%"></label></div><div class="grid2"><div>${rowPlans('yearly','연간')}${rowPlans('monthly','월간')}</div><div>${rowPlans('weekly','주간')}${rowPlans('daily','일간')}</div></div><div class="footer-actions"><button class="btn alt" id="draftPlan">추천 기초계획 불러오기</button><button class="btn alt" id="planSave">내 계획 저장</button><button class="btn" id="planCheck">목표 연결·부담 검토 →</button></div><div class="divider"></div><label class="check"><input type="checkbox" id="llmConsent"><span>선택: 학습계획만 외부 생성형 AI 서비스로 보내 추가 검토받는 데 동의합니다. 학생부·성적표·계정정보는 전송하지 않습니다. API 키가 없으면 로컬 규칙 검토만 제공됩니다.</span></label><button class="btn alt" id="aiPlanCheck" style="margin-top:12px">외부 AI 추가 검토(선택)</button><div id="planReview" style="margin-top:20px"></div></div><section class="card airy" style="margin-top:24px" id="calendarMount"></section>`;
 document.querySelectorAll('[data-plan]').forEach(x=>x.oninput=()=>p[x.dataset.plan]=x.type==='number'||x.dataset.plan==='advanceRatio'?+x.value:x.value);
 document.querySelectorAll('[data-planrow]').forEach(x=>x.oninput=()=>p[x.dataset.planrow][+x.dataset.index]=x.value);
 document.querySelectorAll('[data-addplan]').forEach(x=>x.onclick=()=>{p[x.dataset.addplan].push('');plan()});
 document.querySelectorAll('[data-delplan]').forEach(x=>x.onclick=()=>{p[x.dataset.delplan].splice(+x.dataset.index,1);plan()});
 $('planSave').onclick=async()=>{try{await api('/api/plan/save',{plan:p});alertx('학습계획을 저장했습니다.')}catch(e){error(e)}};
 $('draftPlan').onclick=()=>{const area=state.report?.area||'탐구';if(!p.yearly.length)p.yearly=['목표 학과 관련 핵심 교과의 학업기초 확보','학기별 진학요강 변경사항 1회 확인'];if(!p.monthly.length)p.monthly=['취약 과목 단원별 오답 재풀이 20문항','주간 학습 실적 4회 점검'];if(!p.weekly.length)p.weekly=['주 3회 수학 개념·오답 40분','주 2회 국어 또는 영어 독해 30분'];if(!p.daily.length)p.daily=['오늘 학습한 개념 10분 복습','어제 틀린 문제 2개 재풀이'];if(!p.measurement)p.measurement='주간 목표 완료율과 오답 재풀이 정답률';plan();alertx('예시 계획을 불러왔습니다. 반드시 자신의 일정에 맞게 수정하세요.')};
 async function review(useLLM){try{const r=await api('/api/plan/review',{plan:p,useLLM,externalConsent:!!$('llmConsent')?.checked});state.review=r.review;$('planReview').innerHTML=`<div class="soft"><div class="row between"><b>계획 검토 결과</b><span class="pill">참고점수 ${esc(r.review.score)} / 100 (규칙 기반)</span></div>${r.review.issues.length?r.review.issues.map(x=>`<div class="source"><span class="pill amber">${esc(x.level)}</span> ${esc(x.message)}</div>`).join(''):'<p>기본 규칙에서 큰 누락을 발견하지 못했습니다. 실천 가능성을 직접 확인하세요.</p>'}<div class="divider"></div><b>추천 수정 방향</b>${r.review.proposal.map(x=>`<p style="margin:8px 0">• ${esc(x)}</p>`).join('')}${r.review.aiReview?`<div class="divider"></div><h3>외부 AI 참고의견</h3><p style="white-space:pre-line">${esc(r.review.aiReview)}</p>`:''}${r.review.aiError?`<p class="warn">외부 AI 미연결: ${esc(r.review.aiError)}</p>`:''}</div>`;alertx('검토 결과가 생성됐습니다.')}catch(e){error(e)}}
 $('planCheck').onclick=()=>review(false);$('aiPlanCheck').onclick=()=>review(true);renderCalendar()}
async function inbox(){try{state.cases=(await api('/api/me/cases')).cases}catch(e){error(e)};$('pageContent').innerHTML=`${pageHeader('STEP 07 · COUNSELING WORKFLOW','관리자 상담 요청 및 받은 결과','접수된 기록은 관리자만 열람·검토할 수 있고, 최종 확정 결과지는 학생 마이페이지에 도착합니다.')}<div class="card airy"><h3>새 컨설팅 요청</h3><p class="muted">현재 학생정보·설문·성적 기록을 바탕으로 자동 분석 초안을 관리자에게 보냅니다. 공식 학생부 원문은 업로드하지 마세요.</p><label>관리자에게 전달할 질문<textarea id="askMessage" placeholder="예: 과학고 준비와 일반고 진학 사이에서 고민됩니다. 어떤 부분부터 보완해야 할까요?"></textarea></label><div class="footer-actions"><button class="btn" id="submitCase">관리자에게 상담 요청하기</button></div><div class="divider"></div><h3>내 상담 접수·발행 내역</h3><div>${state.cases.length?state.cases.map(x=>`<div class="case-row"><div><b>상담 #${x.id}</b> <span class="pill ${x.status==='published'?'green':'amber'}">${x.status==='published'?'최종 결과 도착':x.status==='reviewing'?'관리자 검토 중':'접수 완료'}</span><div class="subtle">${esc(x.updated)}</div></div><div class="row"><button class="btn alt small" data-open-case="${x.id}">상세</button>${x.status==='published'?`<a class="btn small" href="/api/download/${x.id}.pdf">PDF</a><a class="btn alt small" href="/api/download/${x.id}.docx">한글 호환 문서</a>`:''}</div></div>`).join(''):'<div class="empty">아직 상담 요청이 없습니다.</div>'}</div><div id="caseDetail"></div><div class="notice warn">현재 구독 요금 월 10,900원은 *상품 설계안*이며 실제 결제·청구·유료이용은 활성화되어 있지 않습니다. .hwp 파일 대신 한글에서 열고 저장할 수 있는 .docx 문서를 제공합니다.</div></div>`; $('submitCase').onclick=async()=>{try{await api('/api/profile/save',{profile:state.profile});await api('/api/answers/save',{answers:state.answers});await api('/api/plan/save',{plan:state.plan});const c=await api('/api/cases/submit',{message:$('askMessage').value});alertx('상담 #'+c.id+'이 관리자에게 접수됐습니다.');inbox()}catch(e){error(e)}};document.querySelectorAll('[data-open-case]').forEach(x=>x.onclick=async()=>{try{const j=await api('/api/cases/'+x.dataset.openCase);const c=j.case,a=JSON.parse(c.auto_report||'{}'),ad=JSON.parse(c.admin_report||'{}');$('caseDetail').innerHTML=`<div class="soft" style="margin-top:20px"><h3>상담 #${c.id} 상세</h3><p>자동 분석: ${esc(a.area)} / ${esc(a.mode)}</p>${c.status==='published'?Object.entries(ad).map(([k,v])=>`<div class="source"><b>${esc(k)}</b><p>${esc(v)}</p></div>`).join(''):'<p>관리자 결과지 검토가 완료되지 않았습니다.</p>'}</div>`}catch(e){error(e)}})}
