 document.querySelectorAll('[data-reassign]').forEach(el=>el.onclick=async()=>{const uid=Number(el.dataset.reassign),sel=document.querySelector('[data-assign-node="'+uid+'"]');if(!sel)return;const nodeId=Number(sel.value);if(!confirm('선택한 학생을 '+nodeId+'조로 옮기시겠습니까?'))return;try{await api('/api/admin/assign-node',{userId:uid,nodeId});alertx('학생 그룹 배정이 변경되었습니다.');students()}catch(e){error(e)}})
