async function catalog(){$('pageContent').innerHTML=`${pageHeader('ADMIN · OFFICIAL DATA','전국 학교·전형 자료 등록','공식 CSV를 가져와 검색 DB를 구성합니다. 학교 목록·모집요강·입결은 서로 다른 데이터입니다.')}<div class="card airy"><div class="notice">[공식 전국학교 원본](https://www.data.go.kr/data/15021148/standard.do)을 관리자가 직접 내려받아 등록하세요. 기본 전국학교 CSV 12,004개는 이미 내장되어 있습니다. 별도 최신 CSV를 관리자가 수동 등록할 수 있으나, 자료 간 시차가 있을 수 있습니다.</div><div class="formgrid"><label>자료 구분<select id="csvKind"><option value="schools">전국 학교 기본 목록</option><option value="admissions">전년도 입학결과</option></select></label><label>공식 자료 URL<input id="csvSource" placeholder="https://www.data.go.kr/..."></label><label class="stretch">CSV 파일 선택<input type="file" id="csvFile" accept=".csv,text/csv"></label></div><button class="btn" id="csvImport">출처와 CSV 등록</button><div class="divider"></div><h3>등록 시 적용되는 안전 규칙</h3><p>학교 CSV에 학교 유형 컬럼이 없으면 '미확인'으로 저장합니다. 고입 결과 CSV는 모집인원과 지원자수·학년도만 보관하며 공식 판정값으로 취급하지 않습니다. 입결을 학생 개인 합격확률로 변환하지 않습니다.</p><div class="row"><a href="학교목록_업로드_양식.csv" download class="btn alt small">학교 목록 CSV 양식</a><a href="입결_업로드_양식.csv" download class="btn alt small">입결 CSV 양식</a></div></div>`;
 $('csvImport').onclick=async()=>{let f=$('csvFile').files[0];if(!f)return alertx('CSV를 선택하세요.');try{let t=await f.text();let r=await api('/api/admin/import',{kind:$('csvKind').value,source:$('csvSource').value,csv:t});alertx(r.imported+'개 항목이 등록됐습니다. 지원자격은 원문 별도 검토.')}catch(e){error(e)}}}
async function boot(){try{const [session,publicData,q]=await Promise.all([api('/api/session'),api('/api/public'),api('/api/questions')]);state.user=session.user;state.csrf=session.csrf||'';state.nodeId=Number(publicData.nodeId)||1;state.nodeCount=Number(publicData.nodeCount)||1;state.nodeCapacity=Number(publicData.nodeCapacity)||25;state.official=publicData.sources||[];state.questions=q.questions||[];if(state.user){state.page=state.user.role==='admin'?'queue':'start';if(state.user.role==='student'){let p=await api('/api/profile');Object.assign(state.profile,p.profile||{});state.answers=p.answers||{};Object.assign(state.plan,p.plan||{});for(const k of ['daily','weekly','monthly','yearly'])if(!Array.isArray(state.plan[k]))state.plan[k]=[];if(!Array.isArray(state.plan.calendar))state.plan.calendar=[];}render()}else renderLogin()}catch(e){$('root').innerHTML=`<div class="login-screen"><section class="login-art"><img src="assets/flight-path.webp" alt="활주로">${brand()}<h1>PATHFINDER EDU</h1></section><section class="login-panel"><div class="login-box"><h2>로컬 서버 실행이 필요합니다.</h2><p>이 서비스는 계정·학생정보·관리자 상담을 안전하게 분리하기 위해 단순 HTML 더블클릭으로는 실행할 수 없습니다.</p><p>압축파일에서 <b>실행_윈도우.bat</b>를 더블클릭하고 브라우저에서 <code>http://127.0.0.1:8765/</code>을 열어주세요.</p><div class="notice">서버 연결 문제: ${esc(e.message)}</div></div></section></div>`}}

/* Added features: editable rolling calendar, transparent readiness charts, verified school references. */
function isoDay(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function mondayFor(d){let x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()-((x.getDay()+6)%7));return x}
function safeWeek(){return state.calendarWeek?new Date(state.calendarWeek+'T12:00:00'):new Date()}
function calEntries(){if(!Array.isArray(state.plan.calendar))state.plan.calendar=[];return state.plan.calendar}
function renderCalendar(){let root=$('calendarMount');if(!root)return;const mon=mondayFor(safeWeek());state.calendarWeek=isoDay(mon);const days=Array.from({length:7},(_,i)=>{const x=new Date(mon);x.setDate(x.getDate()+i);return isoDay(x)});const events=calEntries();const sums={};for(let d of days)sums[d]=events.filter(e=>e.date===d).reduce((s,e)=>s+(Number(e.minutes)||0),0);const finished=events.filter(x=>x.done).reduce((s,x)=>s+(+x.minutes||0),0);const total=events.reduce((s,x)=>s+(+x.minutes||0),0);
 root.innerHTML=`<div class="calendar-header"><div><div class="eyebrow">WEEKLY STUDY PLANNER</div><h2>일정을 하나씩 추가하는 주간 캘린더</h2><p class="muted">날짜·과목·학습시간을 자유롭게 편집하고 완료 상태를 기록하세요. 다른 요일로 끌어다 놓을 수도 있습니다.</p></div><div class="row"><button class="btn alt small" id="weekPrev">← 지난주</button><strong>${days[0]} ~ ${days[6]}</strong><button class="btn alt small" id="weekNext">다음주 →</button><button class="btn alt small" id="weekNow">이번주</button></div></div><div class="calendar-stats"><span>이번 주 계획 <b>${Object.values(sums).reduce((a,b)=>a+b,0)}분</b></span><span>등록된 전체 과제 <b>${events.length}개</b></span><span>전체 실행률 <b>${total?Math.round(100*finished/total)+'%':'측정 전'}</b></span></div><div class="week-grid">${days.map((day,i)=>`<div class="day-cell" data-dropday="${day}"><div class="day-label"><strong>${['월','화','수','목','금','토','일'][i]} <span>${day.slice(5)}</span></strong><button class="day-add" aria-label="${day}에 계획 추가" data-addday="${day}">＋</button></div><div class="day-time ${sums[day]>300?'over':''}">${sums[day]}분</div>${events.filter(e=>e.date===day).map(e=>`<div class="study-event ${e.done?'finished':''}" draggable="true" data-dragid="${esc(e.id)}" title="다른 요일로 끌어 이동"><div class="row between"><b>${esc(e.title)}</b><input type="checkbox" aria-label="${esc(e.title)} 완료" data-done="${esc(e.id)}" ${e.done?'checked':''}></div><div class="event-meta">${esc(e.subject||'자율학습')} · ${Number(e.minutes)||0}분</div><div class="row"><button class="mini-link" data-editid="${esc(e.id)}">수정</button><button class="mini-link delete" data-deleteid="${esc(e.id)}">삭제</button></div></div>`).join('')}<button class="day-placeholder" data-addday="${day}">+ 계획 추가</button></div>`).join('')}</div><form id="eventForm" class="event-form"><h3 id="eventFormTitle">학습 계획 추가</h3><div class="formgrid"><label>날짜<input required id="eventDate" type="date" value="${days[0]}"></label><label>과목·분류<select id="eventSubject"><option>수학</option><option>영어</option><option>국어</option><option>과학</option><option>사회</option><option>복습·오답</option><option>선행학습</option><option>면접 준비</option><option>진로 탐색</option><option>기타</option></select></label><label class="stretch">할 일<input id="eventTitle" maxlength="120" required placeholder="예: 수학 함수 단원 15문제 + 오답 정리"></label><label>소요 시간(분)<input required id="eventMinutes" type="number" min="5" max="480" step="5" value="40"></label><label>주제·실천 방법(선택)<input id="eventNote" maxlength="240" placeholder="어느 단원·교재를 어디까지 할지"></label></div><div class="row"><button class="btn" type="submit">계획에 추가·수정</button><button class="btn alt" id="eventReset" type="button">입력 초기화</button><button class="btn alt" id="calendarSave" type="button">캘린더 서버에 저장</button></div><p class="fieldhint">실제 기록된 계획의 완료율만 표시하며, 합격 가능성과는 다릅니다.</p></form>`;
 const navigate=(n)=>{let d=mondayFor(safeWeek());d.setDate(d.getDate()+n*7);state.calendarWeek=isoDay(d);renderCalendar()};$('weekPrev').onclick=()=>navigate(-1);$('weekNext').onclick=()=>navigate(1);$('weekNow').onclick=()=>{state.calendarWeek=isoDay(mondayFor(new Date()));renderCalendar()};
 const reset=()=>{state.editEventId=null;$('eventForm').reset();$('eventDate').value=days[0];$('eventFormTitle').textContent='학습 계획 추가'};$('eventReset').onclick=reset;
 document.querySelectorAll('[data-addday]').forEach(b=>b.onclick=()=>{reset();$('eventDate').value=b.dataset.addday;$('eventTitle').focus()});
 document.querySelectorAll('[data-editid]').forEach(b=>b.onclick=()=>{let item=events.find(e=>String(e.id)===b.dataset.editid);if(!item)return;state.editEventId=item.id;$('eventDate').value=item.date;$('eventSubject').value=item.subject||'기타';$('eventTitle').value=item.title;$('eventMinutes').value=item.minutes;$('eventNote').value=item.note||'';$('eventFormTitle').textContent='학습 계획 수정';$('eventForm').scrollIntoView({behavior:'smooth',block:'center'})});
 document.querySelectorAll('[data-deleteid]').forEach(b=>b.onclick=()=>{if(!confirm('이 학습 과제를 삭제하시겠습니까?'))return;state.plan.calendar=events.filter(e=>String(e.id)!==b.dataset.deleteid);renderCalendar()});
 document.querySelectorAll('[data-done]').forEach(b=>b.onchange=()=>{let item=events.find(e=>String(e.id)===b.dataset.done);if(item)item.done=b.checked;renderCalendar()});
 document.querySelectorAll('[data-dragid]').forEach(el=>el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.dragid);e.dataTransfer.effectAllowed='move'});
 document.querySelectorAll('[data-dropday]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();let i=events.find(x=>String(x.id)===e.dataTransfer.getData('text/plain'));if(i){i.date=el.dataset.dropday;renderCalendar()}}});
 $('eventForm').onsubmit=e=>{e.preventDefault();let item={id:state.editEventId||'e'+Date.now()+Math.floor(Math.random()*1000),date:$('eventDate').value,title:$('eventTitle').value.trim(),subject:$('eventSubject').value,minutes:Number($('eventMinutes').value),note:$('eventNote').value.trim(),done:false};if(!item.title||!item.date||item.minutes<5||item.minutes>480)return alertx('날짜·목표·시간을 확인하세요.');let older=events.find(x=>x.id===state.editEventId);if(older){item.done=older.done;Object.assign(older,item)}else events.push(item);state.calendarWeek=isoDay(mondayFor(new Date(item.date+'T12:00:00')));state.editEventId=null;renderCalendar();alertx('캘린더 초안에 반영했습니다. 서버에도 저장해주세요.')};
 $('calendarSave').onclick=async()=>{try{const r=await api('/api/plan/save',{plan:state.plan});alertx('캘린더 저장 완료'+(r.calendarReview?.issues?.length?' · 시간 부담 경고가 있습니다.':''))}catch(e){error(e)}}
}
function chartSvg(series,max=100){const W=620,H=235,pad=33;if(!series.length)return '<div class="empty">입력된 성적이 없습니다.</div>';const points=series.map((n,i)=>{const x=pad+i*(W-2*pad)/Math.max(1,series.length-1);const y=H-pad-((Math.max(0,Math.min(max,Number(n)||0))/max)*(H-2*pad));return [x,y]});return `<svg class="pf-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="학기별 성적 추이"><line x1="${pad}" x2="${W-pad}" y1="${H-pad}" y2="${H-pad}" stroke="#becbd5"/><line x1="${pad}" x2="${pad}" y1="${pad}" y2="${H-pad}" stroke="#becbd5"/>${[25,50,75,100].map(n=>`<line x1="${pad}" x2="${W-pad}" y1="${H-pad-n/100*(H-2*pad)}" y2="${H-pad-n/100*(H-2*pad)}" stroke="#e4ebef" stroke-dasharray="4 6"/>`).join('')}<polyline fill="none" stroke="#087b9b" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" points="${points.map(p=>p.join(',')).join(' ')}"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="5.3" fill="#0d6380"/><text x="${p[0]}" y="${p[1]-13}" text-anchor="middle" font-size="12" fill="#27445e">${series[i]}</text><text x="${p[0]}" y="${H-9}" text-anchor="middle" font-size="11" fill="#597184">${i+1}회</text>`).join('')}</svg>`}
function dimensionBars(dim){return Object.entries(dim||{}).map(([key,obj])=>{const p=obj.pct;return `<div class="dimension-line"><div class="row between"><strong>${esc(key)}</strong><span>${p===null||p===undefined?'측정 전':p+'%'}</span></div><div class="dimension-track"><div style="width:${Math.max(0,Math.min(100,Number(p)||0))}%"></div></div><small>${esc(obj.basedOn)}</small></div>`}).join('')}
async function trajectory(){try{const [resp,schools]=await Promise.all([api('/api/longitudinal'),api('/api/reference-schools?region='+encodeURIComponent(state.profile.region||'광주'))]);const r=resp.analysis;state.outlook=r;let survey=state.report?.survey||{};let grades=state.profile.middleGrades||{};let selected=Object.keys(grades).filter(x=>(grades[x]||[]).some(v=>v!==''&&v!==null&&v!==undefined));let first=selected[0]||'수학';let vals=(grades[first]||[]).filter(v=>v!==''&&v!==null&&v!==undefined&&isFinite(+v));const target=r.target||'목표 학교 미정';$('pageContent').innerHTML=`${pageHeader('PATHWAY INTELLIGENCE','성적·흥미·목표의 다각도 분석','자료의 충실도와 계획 실행률을 분리하며, 검증되지 않은 합격확률은 표시하지 않습니다.')}<div class="hero-panel banner" style="min-height:160px"><img src="assets/orbit-editorial.webp" alt="미래 진로"><div><p class="eyebrow">LONG-TERM PATHWAY</p><h1>${esc(r.major||'나의 진학 경로 탐색')}</h1><p>목표: ${esc(target)} · ${esc(r.mode)} · 학교별 실적 검증 후 전략 확정</p></div></div><div class="grid2"><section class="card"><h3>학업·진로·계획 4개 관점</h3>${dimensionBars(r.dimensions)}<div class="notice">위 수치는 <b>자료 준비 수준과 실제 수행률</b>입니다. 대학 합격확률이 아닙니다.</div></section><section class="card"><h3>현재 기록 기반 과목별 변화</h3><label>과목 선택<select id="gradeGraphSubject">${selected.map(x=>`<option>${esc(x)}</option>`).join('')||'<option>입력 없음</option>'}</select></label><div id="gradeGraph">${chartSvg(vals)}</div><p class="fieldhint">시험 난이도 차이가 반영되지 않은 입력 원점수 추이입니다. 중학교 점수만으로 대학 합격선을 판단하지 않습니다.</p></section></div><section class="card airy" style="margin-top:20px"><h3>목표 대학까지의 조건 점검</h3><div class="notice warn"><b>현재 개인 합격률: 산출 불가</b><p>${esc(r.probabilityReason)}</p><p>${esc(r.projection)}</p></div><div class="grid2"><div><h3>관리자 상담 후 확인할 항목</h3>${r.scenarioConditions.map(x=>`<div class="source">${esc(x)}</div>`).join('')}</div><div><h3>계획을 세운 후 달라지는 지표</h3><p>확률 대신 <b>목표 완성도·계획 수행률·과목별 실제 성적 변화</b>를 매월 확인합니다.</p><div class="soft">일정 기록: ${r.calendar.totalMinutes}분 / 완료 ${r.calendar.completedMinutes}분 · 실천률 <strong>${r.calendar.completionRate===null?'측정 전':r.calendar.completionRate+'%'}</strong></div><p class="fieldhint">관리자는 학생의 목표 대학·학과와 실제 입학처 원문을 대조해 최종 컨설팅 문서를 발행합니다.</p></div></div><div class="footer-actions"><button class="btn" id="toCalendarFromOutlook">주간 캘린더에서 계획 조정 →</button><button class="btn alt" id="toAdminInbox">관리자 상담 신청·결과 확인</button></div></section><section class="card airy" style="margin-top:20px"><h3>광주 2027학년도 공식 고입 기본계획에서 확인한 학교 예시</h3><p class="muted">이 목록은 2027학년도 유형 참고자료입니다. 모든 지역의 전체 학교나 향후 최종 모집요강을 뜻하지 않습니다.</p><div class="school-sample">${(schools.schools||[]).slice(0,18).map(x=>`<div class="school-item"><strong>${esc(x.name)}</strong><span>${esc(x.school_type)} · ${esc(x.admission_group)}</span></div>`).join('')||'<div class="empty">해당 지역의 검증된 유형 예시가 없습니다. 공식 전국학교 CSV를 관리자에게 요청하세요.</div>'}</div><div class="footer-actions"><a href="https://www.hischool.go.kr/" target="_blank" rel="noopener" class="btn alt">고입정보포털</a><a href="https://www.adiga.kr/" target="_blank" rel="noopener" class="btn alt">대입정보포털</a></div></section>`;let selector=$('gradeGraphSubject');if(selector)selector.onchange=()=>{$('gradeGraph').innerHTML=chartSvg((grades[selector.value]||[]).filter(v=>v!==''&&v!==null&&v!==undefined&&isFinite(+v)))};$('toCalendarFromOutlook').onclick=()=>{state.page='plan';render()};$('toAdminInbox').onclick=()=>{state.page='inbox';render()}}catch(e){error(e)}}

boot();
